window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-27701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυρρίνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2122 na letra μ · nº geral 27701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ramo ou coroa de mirto 2 baga de mirto 3 mercado de mirto ou de coroas de mirto ♦ ἡ Μυρρίνη 4 Mirrina, n. de mulher.</p></section></article>\n<article id=\"entry-dgp-27702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυρρινίτης οἶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2123 na letra μ · nº geral 27702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vinho preparado com bagas de mir­to. 〈μυρρίνη〉</p></section></article>\n<article id=\"entry-dgp-27703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύρρινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2124 na letra μ · nº geral 27703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de mirto ♦ ὁ μύρρινος 2 ponta do mem­bro viril.</p></section></article>\n<article id=\"entry-dgp-27704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυρρινούσιος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2125 na letra μ · nº geral 27704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) do demo de Mirrinunte.</p></section></article>\n<article id=\"entry-dgp-27705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυρσίνη</h1><div class=\"entry-meta\"><span>DGP · ordem 2126 na letra μ · nº geral 27705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μυρρίνη.</p></section></article>\n<article id=\"entry-dgp-27706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυρσινίτης</h1><div class=\"entry-meta\"><span>DGP · ordem 2127 na letra μ · nº geral 27706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μυρρινίτης οἶνος. 〈μυρσίνη〉</p></section></article>\n<article id=\"entry-dgp-27707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύρτον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2128 na letra μ · nº geral 27707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">baga de mirto. 〈μύρτος〉</p></section></article>\n<article id=\"entry-dgp-27708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύρτος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2129 na letra μ · nº geral 27708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mirto, arbusto 2 ramo de mirto 3 baga de mirto. 〈μύρτον〉</p></section></article>\n<article id=\"entry-dgp-27709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύρτων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 2130 na letra μ · nº geral 27709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) delicado; efeminado. 〈μύρτος〉</p></section></article>\n<article id=\"entry-dgp-27710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύρω</h1><div class=\"entry-meta\"><span>DGP · ordem 2131 na letra μ · nº geral 27710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. 3ª pl. poét. μῦρον) 1 escorrer gota a gota ♦ méd. 2 derreter-se em lágrimas; chorar; lamentar-se sobre a sorte de alguém, ἀμφί e ac.</p></section></article>\n<article id=\"entry-dgp-27711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῦς, μυός (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2132 na letra μ · nº geral 27711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rato 2 Anat. músculo.</p></section></article>\n<article id=\"entry-dgp-27712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύσαγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2133 na letra μ · nº geral 27712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação ou palavra abominável; infâmia. 〈μυσάττομαι〉</p></section></article>\n<article id=\"entry-dgp-27713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2134 na letra μ · nº geral 27713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que macula; infame; abominável 2 contaminado; impuro. 〈μύσος〉</p></section></article>\n<article id=\"entry-dgp-27714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσάττομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2135 na letra μ · nº geral 27714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μυσαχθήσομαι, aor. ἐμυσάχθην, perf. desus.) experimentar horror ou aversão por algo, ac. ou ἐπί e dat. 〈μύσος〉</p></section></article>\n<article id=\"entry-dgp-27715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2136 na letra μ · nº geral 27715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Mísia, região da Ásia Menor 2 Mésia, região vizinha da Ilíria.</p></section></article>\n<article id=\"entry-dgp-27716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μύσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2137 na letra μ · nº geral 27716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da Mísia; mísio ♦ τὸ Μύσιον 2 hino fúnebre dos mísios.</p></section></article>\n<article id=\"entry-dgp-27717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύσος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2138 na letra μ · nº geral 27717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação ou palavra abominável; infâmia 2 impureza; contaminação. 〈μύω〉</p></section></article>\n<article id=\"entry-dgp-27718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυσός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 2139 na letra μ · nº geral 27718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 da Mísia 2 da Mésia.</p></section></article>\n<article id=\"entry-dgp-27719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσταγωγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2140 na letra μ · nº geral 27719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 iniciar alguém, ac., em algo, ac. 2 iniciar nos mistérios 3 instruir nos mistérios divinos 4 servir de guia. 〈μυσταγωγός〉</p></section></article>\n<article id=\"entry-dgp-27720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσταγωγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2141 na letra μ · nº geral 27720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">iniciação nos mistérios. 〈μυστα­γωγός〉</p></section></article>\n<article id=\"entry-dgp-27721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσταγωγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2142 na letra μ · nº geral 27721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sacerdote encarregado de iniciar fiéis nos mistérios; mistagogo 2 guia; cicerone nos templos. 〈μύστης, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-27722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύσταξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2143 na letra μ · nº geral 27722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o lábio superior.</p></section></article>\n<article id=\"entry-dgp-27723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2144 na letra μ · nº geral 27723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rito secreto; mistério: ἡ τελετὴ τῶν μυστηρίων isócr. a iniciação nos mistérios 2 pl., em Atenas, os mistérios de Elêusis: τὰ μικρὰ μυστήρια os pequenos mistérios, em honra de Perséfone, τὰ μεγάλα μυστήρια os grandes mistérios, em honra de Deméter 3 objeto ou ornamento do culto 4 mistério; segredo 5 bíbl. mistério revelado; verdade religiosa 6 crist. sacramento. 〈μύω〉</p></section></article>\n<article id=\"entry-dgp-27724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστηριώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2145 na letra μ · nº geral 27724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 semelhante aos mistérios 2 de natureza secreta 3 concernente aos ritos sagrados. 〈μυστήριον, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-27725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστηριῶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2146 na letra μ · nº geral 27725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) relativo aos mistérios; dos ou pelos mistérios: μυστ. σπονδή ésqn. trégua durante a celebração dos mistérios de Elêusis. 〈μυστήριον〉</p></section></article>\n<article id=\"entry-dgp-27726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύστης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2147 na letra μ · nº geral 27726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) iniciado nos mistérios. 〈μύω〉</p></section></article>\n<article id=\"entry-dgp-27727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2148 na letra μ · nº geral 27727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne aos mistérios; místico 2 que tem um significado espiritual oculto ♦ τὰ μυστικά 3 as cerimônias dos mistérios. 〈μύω〉</p></section></article>\n<article id=\"entry-dgp-27728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 2149 na letra μ · nº geral 27728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo místico; misticamente 2 secretamente; misteriosamente.</p></section></article>\n<article id=\"entry-dgp-27729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστιλάομαι, μυστίλη, μυστίλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2150 na letra μ · nº geral 27729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μιστυλάομαι, μισ­τύλη, μιστύλλω.</p></section></article>\n<article id=\"entry-dgp-27730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2151 na letra μ · nº geral 27730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">odioso; execrável; abominável. 〈μύσος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-27731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυτιληναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2152 na letra μ · nº geral 27731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Mitilene; mitileno. 〈Μυτιλήνη〉</p></section></article>\n<article id=\"entry-dgp-27732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυτιλήνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2153 na letra μ · nº geral 27732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Mitilene, principal cidade de Lesbos.</p></section></article>\n<article id=\"entry-dgp-27733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2154 na letra μ · nº geral 27733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte interna dos moluscos correspondente ao fígado 2 líquido escuro expelido pela sépia. 〈μύω〉</p></section></article>\n<article id=\"entry-dgp-27734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύχιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2155 na letra μ · nº geral 27734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está na parte interna, no profundo; interior. 〈μυχός〉</p></section></article>\n<article id=\"entry-dgp-27735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυχμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2156 na letra μ · nº geral 27735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">murmúrio. 〈μύζω〉</p></section></article>\n<article id=\"entry-dgp-27736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυχόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2157 na letra μ · nº geral 27736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. do fundo ou do interior (da casa). 〈μυχός, -θεν〉</p></section></article>\n<article id=\"entry-dgp-27737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυχοίτατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2158 na letra μ · nº geral 27737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está bem no fundo. 〈μυχός〉</p></section></article>\n<article id=\"entry-dgp-27738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυχόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 2159 na letra μ · nº geral 27738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. para o fundo; para o interior. 〈μυχός, -δε〉</p></section></article>\n<article id=\"entry-dgp-27739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυχός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2160 na letra μ · nº geral 27739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 a parte mais baixa ou profunda ou interna de algo 2 a parte mais recuada (de uma casa, de um quarto, de uma gruta) 3 o interior (de uma cidade, de um país, de uma montanha) 4 a entrada (de um porto, de um golfo) 5 o fundo (do mar, da terra) 6 o profundo ou interior (da alma, da inteligência).</p></section></article>\n<article id=\"entry-dgp-27740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2161 na letra μ · nº geral 27740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. μεμυκώς) 1 fechar-se; estar fechado, cerrado 2 ter a boca ou os olhos fechados; silenciar.</p></section></article>\n<article id=\"entry-dgp-27741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2162 na letra μ · nº geral 27741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de rato 2 semelhante a rato 3 do músculo; muscular. 〈μῦς, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-27742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2163 na letra μ · nº geral 27742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">músculo; cadeia muscular. 〈μῦς〉</p></section></article>\n<article id=\"entry-dgp-27743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυωπάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2164 na letra μ · nº geral 27743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. enxergar pouco; ser míope. 〈μυώψ〉</p></section></article>\n<article id=\"entry-dgp-27744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυωπία1, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2165 na letra μ · nº geral 27744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">miopia. 〈μυώψ〉</p></section></article>\n<article id=\"entry-dgp-27745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυωπία2, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2166 na letra μ · nº geral 27745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">buraco de ratos ou de ratazana. 〈μῦς, ὀπή〉</p></section></article>\n<article id=\"entry-dgp-27746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύωψ, ωπος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2167 na letra μ · nº geral 27746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tavão, mosca que pica os cavalos e bois 2 esporão; aguilhão 3 tormento; angústia.</p></section></article>\n<article id=\"entry-dgp-27747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυώψ, ῶπος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2168 na letra μ · nº geral 27747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quem aperta os olhos para enxergar melhor; míope. 〈μύω, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-27748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωκάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2169 na letra μ · nº geral 27748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 escarnecer ♦ pas. 2 ser objeto de es­cárnio, de zombaria. 〈μῶκος〉</p></section></article>\n<article id=\"entry-dgp-27749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωκία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2170 na letra μ · nº geral 27749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">careta; micagem; zombaria. 〈μῶκος〉</p></section></article>\n<article id=\"entry-dgp-27750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2171 na letra μ · nº geral 27750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">zombaria; caçoada. 〈μωκάω〉</p></section></article>\n<article id=\"entry-dgp-27751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωκός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2172 na letra μ · nº geral 27751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">zombeteiro; zombador.</p></section></article>\n<article id=\"entry-dgp-27752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2173 na letra μ · nº geral 27752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trabalho penoso; fadiga de batalha; esforço.</p></section></article>\n<article id=\"entry-dgp-27753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶλυ, υος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2174 na letra μ · nº geral 27753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">móli, planta fictícia de raízes negras e flores brancas com propriedades mágicas.</p></section></article>\n<article id=\"entry-dgp-27754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωλωπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2175 na letra μ · nº geral 27754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐμωλώπισα, part. perf. pas. μεμωλω­πισμένος) 1 bater forte; percutir 2 cobrir de golpes 3 mortificar. 〈μώλωψ〉</p></section></article>\n<article id=\"entry-dgp-27755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μώλωψ, ωπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2176 na letra μ · nº geral 27755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">marca de golpes de ferimentos. 〈μῶ­λος, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-27756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2177 na letra μ · nº geral 27756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. μῶσθαι, part. μώμενος, fem. dór. μωμένα) ter como propósito; desejar; aspirar a, ac. ou inf.</p></section></article>\n<article id=\"entry-dgp-27757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωμάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2178 na letra μ · nº geral 27757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μωμήσομαι, aor. ἐμωμησάμην, perf. desus.) apontar defeito em; escarnecer; zombar de, ac. 〈μῶμος〉</p></section></article>\n<article id=\"entry-dgp-27758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωμεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2179 na letra μ · nº geral 27758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = μωμάομαι.</p></section></article>\n<article id=\"entry-dgp-27759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωμητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2180 na letra μ · nº geral 27759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">digno de reprovação; censurável. 〈μω­μάομαι〉</p></section></article>\n<article id=\"entry-dgp-27760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2181 na letra μ · nº geral 27760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 censura; reprovação; crítica 2 zombaria 3 defeito; mácula; mancha ♦ ὁ Μῶμος 4 Momo, person.</p></section></article>\n<article id=\"entry-dgp-27761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶν</h1><div class=\"entry-meta\"><span>DGP · ordem 2182 na letra μ · nº geral 27761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partíc. inter. usada quando se espera resposta neg., μῶν οὖν; μῶν οὐ; μῶν οὐκ; μῶν μή; será que? pois bem, será? será que não… 〈μή, οὖν〉</p></section></article>\n<article id=\"entry-dgp-27762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶνυξ, υχος</h1><div class=\"entry-meta\"><span>DGP · ordem 2183 na letra μ · nº geral 27762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de casco inteiriço; que não tem o casco fendido; solípede. 〈μόνος, ὄνυξ〉</p></section></article>\n<article id=\"entry-dgp-27763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μώνυχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2184 na letra μ · nº geral 27763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μῶνυξ.</p></section></article>\n<article id=\"entry-dgp-27764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μώομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2185 na letra μ · nº geral 27764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só imper. pres. 2ª sing. μώεο) = μῶμαι.</p></section></article>\n<article id=\"entry-dgp-27765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2186 na letra μ · nº geral 27765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μωρανῶ, aor. ἐμώρανα; pas. aor. ἐμωράν­θην, perf. μεμώραμαι) 1 estar embotado, confuso, louco; agir ou falar tolamente: πεῖραν μωρ. ésql. tentar tolamente uma ação 2 tornar tolo; embotar 3 tornar louco; enlouquecer. 〈μωρός〉</p></section></article>\n<article id=\"entry-dgp-27766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2187 na letra μ · nº geral 27766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 loucura 2 loucura amorosa; luxúria. 〈μω­ρός〉</p></section></article>\n<article id=\"entry-dgp-27767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωροκλέπτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2188 na letra μ · nº geral 27767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ladrão atrapalhado ou confuso. 〈μωρός, κλέπτης〉</p></section></article>\n<article id=\"entry-dgp-27768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2189 na letra μ · nº geral 27768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dizer asneiras; falar tolamente. 〈μῶρος, λόγος〉</p></section></article>\n<article id=\"entry-dgp-27769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρολόγημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2190 na letra μ · nº geral 27769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">linguagem insensata. 〈μωρο­λογέω〉</p></section></article>\n<article id=\"entry-dgp-27770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρός, ά, όν,</h1><div class=\"entry-meta\"><span>DGP · ordem 2191 na letra μ · nº geral 27770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. μῶρος, α e ος, ον 1 enfraquecido; embotado; confuso 2 tolo 3 louco; insensato 4 insípido ♦ τὸ μῶρον 5 desejo impuro.</p></section></article>\n<article id=\"entry-dgp-27771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρόσοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2192 na letra μ · nº geral 27771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tolamente sábio ou sabiamente tolo. 〈μωρός, σοφός〉</p></section></article>\n<article id=\"entry-dgp-27772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 2193 na letra μ · nº geral 27772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. tolamente; confusamente.</p></section></article>\n<article id=\"entry-dgp-27773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μωσῆς, ῆος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2194 na letra μ · nº geral 27773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Moisés, legislador dos judeus.</p></section></article>\n<article id=\"entry-dgp-27774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μώμενος, μῶσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2195 na letra μ · nº geral 27774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μῶμαι.</p></section></article>\n<article id=\"entry-dgp-27775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ν, ν (νῦ) (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1 na letra ν · nº geral 27775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ny, 13ª letra do alfabeto grego ♦ num. 2 νʹ = 50 ou 50º 3 ͵ν = 50.000 ou 50.000º.</p></section></article>\n<article id=\"entry-dgp-27776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναέτης, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2 na letra ν · nº geral 27776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante. 〈ναίω1〉</p></section></article>\n<article id=\"entry-dgp-27777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναζαρά</h1><div class=\"entry-meta\"><span>DGP · ordem 3 na letra ν · nº geral 27777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Ναζαρέτ indecl. (ἡ) bíbl. Nazaré, cidade da Ga­liléia.</p></section></article>\n<article id=\"entry-dgp-27778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναζαρηνός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4 na letra ν · nº geral 27778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. habitante de Nazaré; nazareno. 〈Ναζαρέτ〉</p></section></article>\n<article id=\"entry-dgp-27779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναζωραῖος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5 na letra ν · nº geral 27779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) bíbl. de Nazaré; nazareno. 〈Ναζαρέτ〉</p></section></article>\n<article id=\"entry-dgp-27780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναί</h1><div class=\"entry-meta\"><span>DGP · ordem 6 na letra ν · nº geral 27780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sim: ναὶ μήν, ναὶ δή, ναὶ μέν, ναὶ μέντοι sim, certamente; em fórm. de juramento, ναὶ μὰ ∆ία por Zeus, ναὶ μὰ τόν (subent. θεόν) pelo deus, ναὶ τὰν Κόραν pela Virgem; como resposta, ναὶ ναί sim certamente.</p></section></article>\n<article id=\"entry-dgp-27781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναΐ</h1><div class=\"entry-meta\"><span>DGP · ordem 7 na letra ν · nº geral 27781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. dór. de ναῦς.</p></section></article>\n<article id=\"entry-dgp-27782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναιάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 8 na letra ν · nº geral 27782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ναΐς.</p></section></article>\n<article id=\"entry-dgp-27783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναιέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 9 na letra ν · nº geral 27783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ναιέμεναι inf. pres. ép., ναίεσκε 3a sing. impf. iter., de ναίω.</p></section></article>\n<article id=\"entry-dgp-27784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναιετάασκον</h1><div class=\"entry-meta\"><span>DGP · ordem 10 na letra ν · nº geral 27784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de ναιετάω.</p></section></article>\n<article id=\"entry-dgp-27785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναιετάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 11 na letra ν · nº geral 27785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf. e impf. iter. ναιετάασκον) 1 (pessoa) habitar em, ac., dat. ou ἐν e dat. 2 (cidade) estar si­tuado; encontrar-se 3 (lugar) existir. 〈ναίω1〉</p></section></article>\n<article id=\"entry-dgp-27786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναῖον</h1><div class=\"entry-meta\"><span>DGP · ordem 12 na letra ν · nº geral 27786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. poét. de ναίω ou de νάω.</p></section></article>\n<article id=\"entry-dgp-27787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νάϊος</h1><div class=\"entry-meta\"><span>DGP · ordem 13 na letra ν · nº geral 27787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = νήϊος.</p></section></article>\n<article id=\"entry-dgp-27788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναΐς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 14 na letra ν · nº geral 27788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Náiade, divindade das fontes e dos cursos d’água.</p></section></article>\n<article id=\"entry-dgp-27789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναίχι</h1><div class=\"entry-meta\"><span>DGP · ordem 15 na letra ν · nº geral 27789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sim, certamente. 〈ναί, -χι〉</p></section></article>\n<article id=\"entry-dgp-27790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναίω1</h1><div class=\"entry-meta\"><span>DGP · ordem 16 na letra ν · nº geral 27790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf. ἔναιον, aor. ἔνασσα poét. νάσσα; pas. aor. ἐνάσ­θην, perf. νένασμαι) 1 (pessoa) habitar; residir; viver em, ac., dat. ou ἐν e dat. 2 (cidade, ilha) situar-se 3 estar cheio de, dat. 4 dar algo, ac., como moradia para alguém, dat.: καί κέ οἱ Ἄργεϊ νάσσα πόλιν hom. e eu lhe teria dado em Argos uma cidade como moradia 5 edificar como moradia: νηὸν ἔνασσαν hom. eles edificaram um templo ♦ at. e méd. 6 deixar alguém, ac., morar em, ἐν e dat.: ἐν Ἄργεϊ ἔνασσεν Ἡρακλέος ἐκγόνους pínd. ele estabeleceu em Argos os descendentes de Héracles, Κέρκυραν, ἔνθα Ποσει­δάων Ἀσωπίδα νάσσατο κούρην a.r. Corcira, onde Posidão estabeleceu uma jovem, filha de Asopo ♦ méd. 7 fundar: μυρία δ’ ἄστη νάσσατο a.r. fundou numerosas cidades ♦ pas. 8 estabelecer-se: πατὴρ ἐμὸς Ἄργεϊ νάσθην hom. meu pai se estabeleceu em Argos 9 ser habitado.</p></section></article>\n<article id=\"entry-dgp-27791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναίω2</h1><div class=\"entry-meta\"><span>DGP · ordem 17 na letra ν · nº geral 27791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = νάω.</p></section></article>\n<article id=\"entry-dgp-27792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νάκη1, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 18 na letra ν · nº geral 27792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νάκος.</p></section></article>\n<article id=\"entry-dgp-27793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νάκη2, ῶν (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 19 na letra ν · nº geral 27793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. de νάκος.</p></section></article>\n<article id=\"entry-dgp-27794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νάκος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 20 na letra ν · nº geral 27794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tosão; peliça.</p></section></article>\n<article id=\"entry-dgp-27795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νακτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 21 na letra ν · nº geral 27795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comprimido; calcado. 〈νάσσω〉</p></section></article>\n<article id=\"entry-dgp-27796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νᾶμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 22 na letra ν · nº geral 27796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 curso d’água; fonte; nascente 2 líquido: ν. βάκχιον ar. líquido báquico, vinho 3 escoamento; derramamento (de lágrimas); fluxo (de palavras); torrente (de fogo) 4 crist. vinho da Eucaristia. 〈νάω〉</p></section></article>\n<article id=\"entry-dgp-27797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναματιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 23 na letra ν · nº geral 27797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de nascente; de fonte; de água corren­te. 〈νᾶμα〉</p></section></article>\n<article id=\"entry-dgp-27798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ναμέρτεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 24 na letra ν · nº geral 27798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. verdade; sinceridade. 〈νημερτής〉</p></section></article>\n<article id=\"entry-dgp-27799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νᾶνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 25 na letra ν · nº geral 27799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 anão 2 espécie de doce ♦ adj. 3 de membros curtos.</p></section></article>\n<article id=\"entry-dgp-27800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νανώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 26 na letra ν · nº geral 27800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante a um anão; muito pequeno. 〈νᾶνος, -ωδης〉</p></section></article>\n";
